H,W=13,19
G=[[1]*W for _ in range(H)]
pattern={( -2,0):4,(-1,0):5,(0,-1):9,(0,0):9,(0,1):3,(1,-1):7,(1,0):5,(1,1):5,(2,0):7}
anchors=[(2,1),(3,17),(5,5),(9,3),(9,16)]
for ar,ac in anchors:
 for (dr,dc),v in pattern.items():
  r,c=ar+dr,ac+dc
  if 0<=r<H and 0<=c<W: G[r][c]=v
print('\n'.join(' '.join(map(str,row)) for row in G))
